<script setup>
import { ref,nextTick,onBeforeUnmount } from 'vue'
import { useLearnerStore } from '@/stores/learner'
import { api } from '@/services/api'
import { speakText,stopSpeaking } from '@/services/audio'
import { useRecording } from '@/composables/useRecording'
const learner=useLearnerStore(),input=ref(''),busy=ref(false),messages=ref([{role:'assistant',content:'我是Alex。想问语法、练一句表达，还是用你的生活写一篇文章？你说就好。'}]),status=ref(''),bottom=ref(null);let controller
const mic=useRecording(t=>{input.value=t}),{recording,error}=mic
const ideas=['用简单英语和我聊家人，一次问一个问题','解释 this is 和 there is 的区别','写一篇适合我的自我介绍，附中文翻译']
async function send(){const text=input.value.trim();if(!text||busy.value)return;mic.stop();input.value='';messages.value.push({role:'user',content:text});busy.value=true;status.value='Alex正在思考…';controller=new AbortController();const timer=setTimeout(()=>controller.abort(),25000);try{const data=await api('coach',{messages:messages.value.slice(-12),profile:{name:learner.displayName,ageGroup:learner.profile.ageGroup,goal:learner.profile.goal},estimate:learner.placementDone?learner.summary:null,scene:learner.settings.scene,needsHelp:learner.model.outputGaps.filter(g=>!g.resolved).slice(0,5).map(g=>g.word)},controller.signal);messages.value.push({role:'assistant',content:data.reply});status.value=''}catch(e){status.value=e.name==='AbortError'?'等待超时，可以稍后重试。':e.message;input.value=text;messages.value.pop()}finally{clearTimeout(timer);busy.value=false;await nextTick();bottom.value?.scrollIntoView({block:'nearest'})}}
onBeforeUnmount(()=>{controller?.abort();stopSpeaking()})
</script>
<template><section class="chat"><header class="page-head"><div class="chat-brand"><img src="/assets/alex-mentor.png" alt="Alex"/><div><h1>Alex 智能陪练</h1><p>自由提出实时要求，难度随你的学习情况调整。</p></div></div><RouterLink to="/learn" class="btn btn-secondary">回到文章</RouterLink></header><div class="panel conversation"><div class="messages"><article v-for="(m,i) in messages" :key="i" class="bubble" :class="m.role"><span class="role">{{m.role==='user'?'你':'Alex'}}</span><p>{{m.content}}</p><button v-if="m.role==='assistant'&&i" class="btn btn-ghost" @click="speakText(m.content)">听回复</button></article><div ref="bottom"/></div><div class="composer"><div v-if="messages.length===1" class="suggestions"><button v-for="idea in ideas" :key="idea" @click="input=idea">{{idea}}</button></div><label class="sr-only" for="chat-input">对Alex说</label><textarea id="chat-input" v-model="input" rows="3" maxlength="4000" placeholder="想聊什么，或想让Alex为你做什么？" @keydown.ctrl.enter.prevent="send" @keydown.meta.enter.prevent="send"/><div class="compose-actions"><button class="btn btn-secondary" :disabled="busy" @click="mic.start">{{recording?'停止录音':'语音输入'}}</button><span class="muted">文字对话 · 非实时语音通话</span><button class="btn btn-primary" :disabled="busy||!input.trim()" @click="send">{{busy?'正在回复…':'发送'}}</button></div><p v-if="status||error" role="status" class="notice">{{status||error}}</p></div></div></section></template>
<style scoped>.chat{max-width:960px;margin:auto}.chat-brand{display:flex;align-items:center;gap:18px}.chat-brand img{width:52px}.chat-brand h1{font-size:30px}.conversation{overflow:hidden}.messages{min-height:300px;max-height:60vh;overflow:auto;padding:28px;display:flex;flex-direction:column;gap:20px}.bubble{max-width:88%;border-radius:16px;background:linear-gradient(135deg,rgba(200,244,91,.08),rgba(255,255,255,.025));border:1px solid rgba(200,244,91,.1);padding:17px 22px}.bubble.user{align-self:flex-end;background:linear-gradient(135deg,rgba(83,206,255,.12),rgba(130,104,255,.08));border-color:rgba(83,206,255,.15)}.bubble p{white-space:pre-wrap;line-height:1.85;font-size:15px;margin:6px 0}.role{font-size:11px;color:var(--ink-muted)}.bubble .btn{font-size:11px;min-height:30px;padding:0}.composer{border-top:1px solid var(--line);padding:22px}.suggestions{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.suggestions button{border:1px solid var(--line);background:rgba(255,255,255,.04);color:var(--ink-muted);border-radius:20px;padding:7px 11px;font-size:11px}.suggestions button:hover{color:var(--ink);border-color:rgba(200,244,91,.3)}.compose-actions{display:flex;align-items:center;gap:12px;margin-top:12px}.compose-actions span{font-size:11px;flex:1}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:750px){.messages{padding:16px}.bubble{max-width:100%;padding:15px}.compose-actions span{display:none}.compose-actions .btn:last-child{margin-left:auto}.chat-brand h1{font-size:24px}}</style>
